"use client";

import { AnimatePresence, LayoutGroup, motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, type KeyboardEvent, type ReactNode, useId, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** One card in the list. The title and summary always show; the details show while the card is open. */
export interface ExpandCardItem {
  id: string;
  title: ReactNode;
  /** A second line under the title, for example "3 nights". */
  summary?: ReactNode;
  /** Sits at the end of the row, for example a price. */
  trailing?: ReactNode;
  details: ReactNode;
}

/**
 * Props for a list of expanding cards. `value` is the open card's id, or `null`
 * when all are closed: pass it to control the list, or `defaultValue` to let
 * the list hold its own state.
 */
export type ExpandCardProps = Omit<ComponentPropsWithoutRef<"ul">, "children" | "defaultValue"> & {
  items: ExpandCardItem[];
  value?: string | null;
  defaultValue?: string | null;
  onValueChange?: (value: string | null) => void;
};

// Damping 42 is just over 2 × √420: critically damped, so the cards settle without a bounce.
const RESIZE: Transition = { type: "spring", stiffness: 420, damping: 42, mass: 1 };
const REVEAL: Transition = { duration: 0.2, ease: [0.165, 0.84, 0.44, 1] };
const HIDE: Transition = { duration: 0.1 };
// Motion keeps a radius round while it scales a card only when the radius is a style it can read.
const RADIUS = 16;

function ChevronGlyph({ open }: { open: boolean }) {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="currentColor"
      aria-hidden="true"
      className={cn("size-4 shrink-0 text-muted-foreground motion-safe:transition-transform motion-safe:duration-200", open && "rotate-180")}
    >
      <path d="M3.2 5.7a1 1 0 0 1 1.4 0L8 9.1l3.4-3.4a1 1 0 1 1 1.4 1.4l-4.1 4.1a1 1 0 0 1-1.4 0L3.2 7.1a1 1 0 0 1 0-1.4Z" />
    </svg>
  );
}

/**
 * A list of compact cards. Pressing one opens it in place to show its details,
 * and the cards below move aside. Only one card is open at a time, and Escape
 * closes it.
 */
export function ExpandCard({ items, value, defaultValue = null, onValueChange, className, onKeyDown, ...listProps }: ExpandCardProps) {
  const [ownValue, setOwnValue] = useState<string | null>(defaultValue);
  const open = value === undefined ? ownValue : value;
  const reduceMotion = useReducedMotion() ?? false;
  const baseId = useId();
  const triggers = useRef(new Map<string, HTMLButtonElement>());

  const change = (next: string | null) => {
    if (value === undefined) setOwnValue(next);
    onValueChange?.(next);
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLUListElement>) => {
    onKeyDown?.(event);
    if (event.defaultPrevented || event.key !== "Escape" || open === null) return;
    // Focus may sit in the details that are about to leave, so it goes back to their trigger.
    triggers.current.get(open)?.focus();
    change(null);
  };

  return (
    <LayoutGroup id={baseId}>
      <ul {...listProps} onKeyDown={handleKeyDown} className={cn("flex w-full max-w-sm flex-col gap-2", className)}>
        {items.map((item) => {
          const isOpen = item.id === open;
          const triggerId = `${baseId}-${item.id}-trigger`;
          const panelId = `${baseId}-${item.id}-panel`;

          return (
            <motion.li
              key={item.id}
              layout={!reduceMotion}
              transition={RESIZE}
              style={{ borderRadius: RADIUS }}
              className="relative overflow-hidden border border-border bg-card text-foreground"
            >
              <motion.div layout={reduceMotion ? false : "position"} transition={RESIZE}>
                <button
                  ref={(node) => {
                    if (node) triggers.current.set(item.id, node);
                    else triggers.current.delete(item.id);
                  }}
                  type="button"
                  id={triggerId}
                  aria-expanded={isOpen}
                  aria-controls={panelId}
                  onClick={() => change(isOpen ? null : item.id)}
                  className="flex min-h-14 w-full cursor-pointer touch-manipulation items-center gap-3 rounded-2xl px-4 py-2 text-left text-sm outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring"
                >
                  <span className="flex min-w-0 flex-1 flex-col">
                    <span className="truncate font-medium">{item.title}</span>
                    {item.summary ? <span className="truncate text-muted-foreground">{item.summary}</span> : null}
                  </span>
                  {item.trailing ? <span className="shrink-0 font-medium tabular-nums">{item.trailing}</span> : null}
                  <ChevronGlyph open={isOpen} />
                </button>
              </motion.div>
              {/* popLayout lifts closing details out of the flow, so the card shrinks while they fade. */}
              <AnimatePresence initial={false} mode="popLayout">
                {isOpen ? (
                  <motion.div
                    key="panel"
                    id={panelId}
                    role="region"
                    aria-labelledby={triggerId}
                    layout={reduceMotion ? false : "position"}
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1, transition: REVEAL }}
                    exit={{ opacity: 0, transition: HIDE }}
                    transition={RESIZE}
                    className="px-4 pb-4 text-sm text-muted-foreground"
                  >
                    {item.details}
                  </motion.div>
                ) : null}
              </AnimatePresence>
            </motion.li>
          );
        })}
      </ul>
    </LayoutGroup>
  );
}
